SELECT array_sort_lambda(array_sort_lambda(ARRAY<TINYINT>[3, 2, 5, 1, 2], (x, y) -> if(`__LAMBDA_TABLE`.`__LAMBDA_TABLE`.`x` < `__LAMBDA_TABLE`.`__LAMBDA_TABLE`.`y`, -1, if(`__LAMBDA_TABLE`.`__LAMBDA_TABLE`.`x` = `__LAMBDA_TABLE`.`__LAMBDA_TABLE`.`y`, 0, 1))), (x, y) -> CASE WHEN (`__LAMBDA_TABLE`.`__LAMBDA_TABLE`.`x` IS NULL) THEN -1 WHEN (`__LAMBDA_TABLE`.`__LAMBDA_TABLE`.`y` IS NULL) THEN 1 WHEN (`__LAMBDA_TABLE`.`__LAMBDA_TABLE`.`x` < `__LAMBDA_TABLE`.`__LAMBDA_TABLE`.`y`) THEN 1 WHEN (`__LAMBDA_TABLE`.`__LAMBDA_TABLE`.`x` = `__LAMBDA_TABLE`.`__LAMBDA_TABLE`.`y`) THEN 0 ELSE -1 END) AS `array_sort(array_sort_lambda([3, 2, 5, 1, 2], (x, y) -> if(__LAMBDA_TABLE.__LAMBDA_TABLE.x < __LAMBDA_TABLE.__LAMBDA_TABLE.y, -1, if(__LAMBDA_TABLE.__LAMBDA_TABLE.x = __LAMBDA_TABLE.__LAMBDA_TABLE.y, 0, 1))), (x, y) -> CASE WHEN (x IS NULL) THEN -1 WHEN (y IS NULL) THEN 1 WHEN (x < y) THEN 1 WHEN (x = y) THEN 0 ELSE -1 END)`;
